/**
 * Creates a Stripe PaymentIntent for the supplied cart. Cart prices are
resolved server-side from the Presentail OS catalog (never from
client-supplied values) so the client cannot manipulate the charge.
Returns a `clientSecret` that the web client passes to Stripe Elements'
`confirmCardPayment`. The `orderId` returned must be used as-is when
submitting the WooCommerce order after payment is confirmed.

 * @summary Create a Stripe PaymentIntent for inline card payment
 */
export const createCheckoutPaymentIntentBodyItemsItemWcIdMin = 0;

export const CreateCheckoutPaymentIntentBody = zod.object({
  items: zod
    .array(
      zod.object({
        wcId: zod
          .number()
          .min(createCheckoutPaymentIntentBodyItemsItemWcIdMin)
          .optional()
          .describe(
            "WooCommerce product ID. Use 0 for OS-native products not mirrored in WooCommerce; supply osSlug in that case.",
          ),
        osSlug: zod
          .string()
          .optional()
          .describe(
            "Presentail OS product slug. Required when wcId is 0 (OS-native product). The server resolves the price from the OS cache by slug.",
          ),
        quantity: zod.number().min(1),
      }),
    )
    .min(1)
    .describe(
      "Cart items. Prices are resolved server-side and never read from the client.",
    ),
  orderId: zod
    .string()
    .describe(
      "App-generated order ID that binds this PaymentIntent to the WooCommerce order.",
    ),
  currency: zod
    .string()
    .optional()
    .describe(
      "ISO 4217 currency code (default USD). The PaymentIntent is charged in this currency.",
    ),
  email: zod
    .string()
    .optional()
    .describe("Shopper email for Stripe receipt. Optional."),
  deliveryFeeUsd: zod
    .number()
    .optional()
    .describe(
      "Client-computed delivery fee in USD (district fee + express surcharge + slot fee). The server adds this to the product subtotal and charges the combined total. Must be >= 0.",
    ),
  district: zod
    .string()
    .optional()
    .describe(
      "Delivery district name. Stored in the payment intent snapshot for audit; delivery fee is taken from deliveryFeeUsd.",
    ),
  expressDelivery: zod
    .boolean()
    .optional()
    .describe(
      "Whether express delivery is selected. Stored in the snapshot for audit; surcharge is included in deliveryFeeUsd.",
    ),
  noAddress: zod
    .boolean()
    .optional()
    .describe(
      'True when the shopper chose \"no address\". Stored in the snapshot for audit.',
    ),
  couponCode: zod
    .string()
    .optional()
    .describe(
      "Promo\/coupon code to apply. The server re-validates the code and deducts the discount from the charged amount. Client-supplied discount amounts are never trusted.",
    ),
  metadata: zod
    .record(zod.string(), zod.string())
    .optional()
    .describe(
      "Extra key-value pairs forwarded to Stripe PaymentIntent metadata.",
    ),
});

export const CreateCheckoutPaymentIntentResponse = zod.object({
  ok: zod.boolean(),
  clientSecret: zod
    .string()
    .describe(
      "Stripe PaymentIntent client_secret. Pass to stripe.confirmCardPayment().",
    ),
  orderId: zod
    .string()
    .describe(
      "The orderId that was bound to this PaymentIntent. Use as-is in \/woo\/order.",
    ),
  amount: zod
    .number()
    .describe("Charge amount in Stripe minor units (e.g. cents for USD)."),
  currency: zod
    .string()
    .describe("ISO 4217 currency code used for the charge."),
});

